<?php
require __DIR__.'/../../backend/vendor/autoload.php';
$app=require __DIR__.'/../../backend/bootstrap/app.php';$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap();
$p=App\Models\ReportingPeriod::whereHas('project',fn($q)=>$q->where('name','like','%Hann%')->orWhere('client_name','like','%Hann%'))->where('start_date','2026-08-01')->with('project.client')->firstOrFail();
$validation=app(App\Services\EvidenceValidation::class)->current($p);$context=app(App\Services\RecordReview::class)->context($p);
$out=['report'=>$p->toArray(),'generations'=>App\Models\ReportGeneration::where('reporting_period_id',$p->id)->latest()->limit(3)->get(),'normalizations'=>App\Models\NormalizationRun::where('reporting_period_id',$p->id)->latest()->limit(3)->get(),'validation'=>$validation?array_diff_key($validation,['records'=>1]):null,'normalization_current'=>$context['current'],'current_normalization_fingerprint'=>$context['fingerprint'],'assessment'=>app(App\Services\SimplifiedReportSharing::class)->assess($p),'documents'=>[]];
foreach($p->documents()->with('currentRun')->get() as $d){$pieces=Illuminate\Support\Facades\DB::table('document_extracted_content')->where('extraction_run_id',$d->current_run_id)->orderBy('ordinal')->get();$out['documents'][]=['document'=>$d->toArray(),'content'=>$pieces,'assets'=>Illuminate\Support\Facades\DB::table('document_assets')->where('extraction_run_id',$d->current_run_id)->get()];}
file_put_contents(__DIR__.'/hanns-period-before.json',json_encode($out,JSON_PRETTY_PRINT));
echo json_encode(['report'=>$p->only(['id','project_id','title','start_date','end_date','status','version','requires_regeneration']),'normalization_current'=>$context['current'],'validation_current'=>$validation['current']??null,'validation_version'=>Illuminate\Support\Facades\DB::table('report_validation_runs')->where('id',$validation['id']??'')->value('rules_version'),'generations'=>$out['generations'],'normalizations'=>$out['normalizations']->map(fn($n)=>$n->only(['id','status','fingerprint','input_snapshot','created_at','completed_at'])),'assessment'=>$out['assessment'],'documents'=>collect($out['documents'])->map(fn($d)=>['id'=>$d['document']['id'],'filename'=>$d['document']['original_filename'],'checksum'=>$d['document']['checksum'],'current_run_id'=>$d['document']['current_run_id'],'extraction_status'=>$d['document']['extraction_status']])],JSON_PRETTY_PRINT);
